// The cockpit holds ONE list of the tools whose question expires, and it is the generated one (theseus-lrc3m, F1).
// `src/lib/heldquestion.ts` imports `EXPIRING_TOOLS` from `protocol.gen/ExpiringTools.ts`, which theseus-protocol's `ts`
// test writes from `work::ask::EXPIRING_TOOLS`. That chain is already guarded at both ends: the gate's "protocol types"
// phase fails when the generated file differs from the commit, and `rpc::question_waits`'s
// `the_protocols_expiring_tools_are_the_cores` pins the core's list to the protocol's.
//
// Nothing guarded the OTHER direction: a THIRD list — a second hand-maintained copy somewhere else in the cockpit —
// which a fourth expiring tool would silently leave behind, so a card would call a real deadline "held". This file is
// that guard. It does not check that today's copies agree; it checks that a copy cannot be written. The names it looks
// for are read from the generated list, so a tool added in Rust widens the guard by itself, and the last test proves
// the detector still fires on a copy built out of whatever the list then holds. The sources are read as text: these are
// React components and modules this runner does not import.
import test from 'node:test'
import assert from 'node:assert/strict'
import { readdirSync, readFileSync, statSync } from 'node:fs'
import { join, relative } from 'node:path'
import { EXPIRING_TOOLS } from '../src/protocol.gen/ExpiringTools.ts'

const ROOT = new URL('..', import.meta.url).pathname
const GEN = join(ROOT, 'src/protocol.gen')

/** Every `.ts`/`.tsx` under `src` and `test`, except the generated directory, which is the one place the list belongs. */
function sources(dir: string): string[] {
  return readdirSync(dir).flatMap((f) => {
    const p = join(dir, f)
    if (statSync(p).isDirectory()) return p === GEN || f === 'node_modules' ? [] : sources(p)
    return /\.tsx?$/.test(p) ? [p] : []
  })
}

/** A run of string literals: two or more quoted strings separated by nothing but `,` `|` and whitespace. An array or
 *  `Set` literal, and a union of string types, all read as one run; `q('a', t), q('b', u)` does not, because the call's
 *  parentheses break it. */
const RUN = /(?:(?:'[^'\n]*'|"[^"\n]*")\s*[,|]\s*)+(?:'[^'\n]*'|"[^"\n]*")/g
const LITERAL = /'([^'\n]*)'|"([^"\n]*)"/g

/** The expiring tools a single run of literals names, in the order the run gives them. */
function toolsInRun(run: string): string[] {
  const names = new Set<string>(EXPIRING_TOOLS as readonly string[])
  return [...run.matchAll(LITERAL)].map((m) => m[1] ?? m[2]).filter((s) => names.has(s))
}

/** Every place a file writes two or more of the generated names together: `path:line` and the names. */
function copiesIn(path: string, text: string): string[] {
  const out: string[] = []
  for (const m of text.matchAll(RUN)) {
    const found = toolsInRun(m[0])
    if (found.length < 2) continue
    const line = text.slice(0, m.index).split('\n').length
    out.push(`${relative(ROOT, path)}:${line} lists ${found.join(', ')}`)
  }
  return out
}

test('the cockpit writes the expiring-tools list in exactly one place: the generated file', () => {
  const copies = [...sources(join(ROOT, 'src')), ...sources(join(ROOT, 'test'))].flatMap((p) =>
    copiesIn(p, readFileSync(p, 'utf8')),
  )
  assert.deepEqual(
    copies,
    [],
    'a second copy of the expiring-tools list: import EXPIRING_TOOLS from protocol.gen/ExpiringTools.ts instead, so a tool added to the Rust list reaches it (theseus-lrc3m, F1)',
  )
})

test('the one consumer reads the generated list, and keeps no literals of its own', () => {
  const held = readFileSync(join(ROOT, 'src/lib/heldquestion.ts'), 'utf8')
  assert.match(held, /import \{ EXPIRING_TOOLS \} from '\.\.\/protocol\.gen\/ExpiringTools\.ts'/)
  // Not one of the names as a string literal: the module may name them in prose, never in code.
  const code = held.split('\n').filter((l) => !l.trimStart().startsWith('//')).join('\n')
  for (const t of EXPIRING_TOOLS) {
    assert.ok(!code.includes(`'${t}'`) && !code.includes(`"${t}"`), `heldquestion.ts writes ${t} as a literal`)
  }
})

test('the generated file says it is generated, and the generator is named in it', () => {
  const gen = readFileSync(join(GEN, 'ExpiringTools.ts'), 'utf8')
  assert.match(gen, /generated by theseus-protocol's `ts` test, from `work::ask::EXPIRING_TOOLS`/)
  assert.match(gen, /Do not edit this file manually/)
  assert.ok(EXPIRING_TOOLS.length > 0, 'an empty list would pass every loop that reads it')
})

test('the guard grows with the Rust list: a copy of what it holds today is still caught', () => {
  // The detector read against planted copies built from the generated list itself. A fourth tool added in Rust makes
  // these samples name it too, so the guard cannot go stale against the list it guards — which is the whole point:
  // the test that matters is not that two lists agree today but that a third cannot be added unnoticed.
  const all = [...EXPIRING_TOOLS] as string[]
  const two = all.slice(0, 2)
  assert.ok(two.length === 2, 'the list holds at least two tools, so a partial copy is possible')
  const whole = `const EXPIRING = [${all.map((t) => `'${t}'`).join(', ')}]`
  const partial = `const SOME = new Set([${two.map((t) => `"${t}"`).join(', ')}])`
  const union = `type Expiring = ${all.map((t) => `'${t}'`).join(' | ')}`
  for (const [what, sample] of [['a whole copy', whole], ['a partial copy', partial], ['a union of the names', union]] as const) {
    assert.ok(copiesIn('planted.ts', sample).length > 0, `${what} goes uncaught: ${sample}`)
  }
  // And what must stay legal: one name alone, and a fixture row that happens to mention two in separate calls.
  assert.deepEqual(copiesIn('planted.ts', `if (c.tool === '${all[0]}') return true`), [])
  assert.deepEqual(copiesIn('planted.ts', `[q('act_a', '${all[0]}', NOW), q('act_b', '${all[1]}', NOW)]`), [])
})
